function editableCanvas(){return editor&&!editor.readOnly&&!editor.busy&&!editor.pending&&!editor.compatibilityIssues?.length;}
function layoutKey(id,version){return 'fc-template-layout:'+JSON.stringify([editor.brandId,id,version]);}
function initialLayout(){
  const nodes=editor.values.nodes,positions={},ranks=new Map(),queue=editor.values.startNodeId?[{id:editor.values.startNodeId,rank:0}]:[];
  while(queue.length){const {id,rank}=queue.shift();if(ranks.has(id))continue;ranks.set(id,rank);const node=nodes.find(n=>n.nodeId===id);(node?.next||[]).forEach(to=>queue.push({id:to,rank:rank+1}));}
  const counts={};nodes.forEach((n,i)=>{const rank=ranks.has(n.nodeId)?ranks.get(n.nodeId):i%3,row=counts[rank]||0;counts[rank]=row+1;positions[n.nodeId]={x:36+(rank%4)*254,y:42+Math.floor(rank/4)*250+row*154};});
  try{const saved=JSON.parse(sessionStorage.getItem(layoutKey(editor.id,editor.viewVersion))||'null');if(editor.id&&saved&&nodes.every(n=>Number.isFinite(saved[n.nodeId]?.x)&&Number.isFinite(saved[n.nodeId]?.y)))nodes.forEach(n=>{positions[n.nodeId]={x:Math.max(12,Math.min(3000,saved[n.nodeId].x)),y:Math.max(12,Math.min(3000,saved[n.nodeId].y))};});}catch(_){}
  return positions;
}
function rememberLayout(result){try{const id=result.data?.templateId||editor.id,version=result.data?.version||Number(editor.expectedVersion||0)+1;if(id)sessionStorage.setItem(layoutKey(id,version),JSON.stringify(editor.positions));}catch(_){} }
function legacyCompatibilityIssues(values){
  const issues=[],knownNode=['nodeId','name','type','duty','methods','next','targetKind'],knownEdge=['edgeId','fromNodeId','toNodeId','conditions'];
  const issue=text=>{if(!issues.includes(text))issues.push(text);};
  (values.nodes||[]).forEach(n=>{
    if(n.type&&!Object.hasOwn(nodeTypes,n.type))issue('节点“'+n.name+'”使用未支持的节点类型 '+n.type+'。');
    if(n.duty&&!Object.hasOwn(duties,n.duty))issue('节点“'+n.name+'”使用未支持的职责 '+n.duty+'。');
    if((n.methods||[]).some(x=>!Object.hasOwn(methods,x)))issue('存在未支持的处理方式。');
    if((n.next||[]).some(id=>!values.nodes.some(target=>target.nodeId===id)))issue('原模板连接指向不存在的节点，不能自动丢弃连接。');
    if(n.type==='END'&&n.next?.length)issue('原模板结束节点含后续出口，不能自动删除出口。');
    if(Object.keys(n).some(k=>!knownNode.includes(k)))issue('存在当前编辑器无法保留的节点扩展字段。');
  });
  const pairs=(values.nodes||[]).flatMap(n=>(n.next||[]).map(to=>JSON.stringify([n.nodeId,to]))),edges=values.edges||[];
  if(values.startNodeId&&!values.nodes.some(n=>n.nodeId===values.startNodeId))issue('原模板起始节点不存在，原配置已保留。');
  if(edges.length!==pairs.length||edges.some(x=>!pairs.includes(JSON.stringify([x.fromNodeId,x.toNodeId])))||new Set(edges.map(x=>JSON.stringify([x.fromNodeId,x.toNodeId]))).size!==edges.length)issue('后续路径与连接记录不一致，不能自动修复或丢弃连接。');
  const directory=conditionDirectory();
  edges.forEach(edge=>{
    if(Object.keys(edge).some(k=>!knownEdge.includes(k)))issue('存在当前编辑器无法保留的连接扩展字段。');
    const c=edge.conditions;if(!c)return;
    if(c.enabled&&!['ALL','ANY'].includes(c.mode))issue('条件使用未支持的组合方式。');
    if(c.rules!==undefined&&!Array.isArray(c.rules)){issue('条件规则结构不受支持。');return;}
    if(Object.keys(c).some(k=>!['enabled','mode','rules'].includes(k)))issue('存在未支持的条件扩展字段。');
    (c.rules||[]).forEach(r=>{
      if(r.operator&&!Object.hasOwn(conditionNames,r.operator))issue('条件使用未支持的判断 '+r.operator+'。');
      if(Object.keys(r).some(k=>!['ruleId','operator','values','fieldId','optionIds'].includes(k)))issue('存在未支持的条件规则扩展字段。');
      if(!c.enabled)return;
      if(directory.status!=='success'){issue('条件目录读取失败，原条件保留，暂不能编辑。');return;}
      if(r.operator==='CALL_STATUS_IN'&&(r.values||[]).some(v=>!directory.data.callStatuses.some(x=>x.value===v)))issue('条件引用了当前目录不可用的通话状态。');
      if(['TAGS_CONTAINS_ANY','TAGS_CONTAINS_ALL'].includes(r.operator)){const field=directory.data.tagFields.find(f=>(f.id||f.fieldId)===r.fieldId);if(!field||(r.optionIds||[]).some(id=>!field.options.some(o=>o.id===id)))issue('条件引用的稳定字段或选项在当前目录不可用。');}
    });
  });
  return issues;
}
function canvasSize(){const positions=Object.values(editor.positions||{});return {width:Math.max(canvasWidth,...positions.map(p=>p.x+230)),height:Math.max(canvasHeight,...positions.map(p=>p.y+150))};}
function canvasLinks(){
  const size=canvasSize(),v=editor.values;
  return '<svg class="fc-canvas-links" aria-label="节点连接" width="'+size.width+'" height="'+size.height+'"><defs><marker id="fcCanvasArrow" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="6" markerHeight="6" orient="auto-start-reverse"><path d="M 0 0 L 10 5 L 0 10 z" fill="#8ea8c6"/></marker></defs>'+v.edges.map(edge=>{
    const from=editor.positions[edge.fromNodeId],to=editor.positions[edge.toNodeId];if(!from||!to)return '';
    const x1=from.x+180,y1=from.y+43,x2=to.x,y2=to.y+43,bend=Math.max(44,Math.abs(x2-x1)*.45);
    const loop=edge.fromNodeId===edge.toNodeId,path=loop?'M '+x1+' '+y1+' C '+(x1+68)+' '+(y1-100)+' '+(from.x-68)+' '+(y1-100)+' '+from.x+' '+y1:'M '+x1+' '+y1+' C '+(x1+bend)+' '+y1+' '+(x2-bend)+' '+y2+' '+x2+' '+y2;
    return '<path class="fc-edge-line" data-canvas-edge="'+e(edge.edgeId)+'" d="'+path+'" fill="none" marker-end="url(#fcCanvasArrow)"/>'+(edge.conditions?.enabled?'<text class="fc-edge-label" x="'+((x1+x2)/2)+'" y="'+((y1+y2)/2-7)+'">附加条件</text>':'');
  }).join('')+'</svg>';
}
function canvasNode(n,index){
  const p=editor.positions[n.nodeId],readonly=editor.readOnly||editor.busy||editor.pending||editor.compatibilityIssues?.length;
  return '<div class="fc-canvas-node'+(editor.selectedNodeId===n.nodeId?' selected':'')+'" role="button" tabindex="0" aria-label="'+e(nodeLabel(n,index))+'，'+e(nodeTypes[n.type]||'待配置类型')+'" aria-pressed="'+(editor.selectedNodeId===n.nodeId)+'" data-canvas-node="'+e(n.nodeId)+'" style="left:'+p.x+'px;top:'+p.y+'px" onclick="'+call('selectCanvasNode',n.nodeId)+'" onkeydown="FlowConfiguration.canvasKey(event,'+e(JSON.stringify(n.nodeId))+')"><div class="fc-canvas-drag-handle"'+(readonly?'':' onpointerdown="FlowConfiguration.beginCanvasMove(event,'+e(JSON.stringify(n.nodeId))+')"')+'><span class="fc-node-type">'+e(nodeTypes[n.type]||'待配置类型')+'</span><span aria-hidden="true">⠿</span></div><strong class="fc-canvas-title" data-canvas-title>'+e(nodeLabel(n,index))+'</strong><div class="fc-node-meta">'+(editor.values.startNodeId===n.nodeId?'<span>起始节点</span> · ':'')+e(duties[n.duty]||'待配置职责')+'</div></div>';
}
function visualEditor(v){
  const readonly=editor.readOnly,locked=readonly||editor.busy||editor.pending||editor.compatibilityIssues?.length,selected=v.nodes.find(n=>n.nodeId===editor.selectedNodeId),size=canvasSize();
  const library=readonly?'':'<aside class="fc-node-library"><h3>节点库</h3><p>拖到画布或点击添加</p>'+Object.entries(nodeTypes).map(([type,label])=>'<button type="button" class="fc-library-node" draggable="'+!locked+'" ondragstart="FlowConfiguration.beginLibraryDrag(event,\''+type+'\')" onclick="FlowConfiguration.addCanvasNode(\''+type+'\')"'+(locked?' disabled':'')+'><strong>'+e(label)+'</strong><small>'+({ASSIGN:'分配办理人员',PROCESS:'人员选择并启动方式',TRANSFER:'手动转交同品牌租户',END:'明确结束路径'}[type])+'</small></button>').join('')+'<button id="fcAddNode" type="button" class="btn" onclick="FlowConfiguration.addRow(\'node\')"'+(locked?' disabled':'')+'>+ 空白节点</button></aside>';
  const canvas='<div class="fc-canvas-column"><div class="fc-canvas-toolbar"><strong>流转画布 <small>'+v.nodes.length+' 个节点 · '+v.edges.length+' 条连接</small></strong><button type="button" class="btn" onclick="FlowConfiguration.arrangeCanvas()"'+(editor.busy||editor.pending?' disabled':'')+'>整理布局</button></div><div class="fc-canvas-viewport" id="fcCanvasViewport"><div id="fcCanvas" class="fc-canvas" style="width:'+size.width+'px;height:'+size.height+'px" ondragover="FlowConfiguration.canvasDragOver(event)" ondrop="FlowConfiguration.dropCanvasNode(event)">'+canvasLinks()+v.nodes.map(canvasNode).join('')+(!v.nodes.length?'<div class="fc-canvas-empty"><strong>从节点库拖入第一个节点</strong><span>再明确配置名称、职责、起始节点与后续路径</span></div>':'')+'</div></div><p class="fc-canvas-hint">拖动节点顶部调整位置；点击节点配置。连接由右侧“允许后续节点”控制，位置不决定执行顺序。</p></div>';
  const panel='<aside class="fc-config-panel"><h3>节点配置</h3><div id="fcNodes">'+(selected?nodeCard(selected,v.nodes.indexOf(selected),v.nodes):'<div class="fc-canvas-empty"><strong>请选择一个节点</strong><span>配置职责、处理方式、后续路径与条件</span></div>')+'</div></aside>';
  const unsupported=editor.compatibilityIssues?.length?'<div class="fc-error" role="alert">原模板含当前编辑器不支持的配置，已保留原内容并阻止保存：'+editor.compatibilityIssues.map(e).join(' ')+'<details><summary>查看原配置</summary><pre>'+e(JSON.stringify(v,null,2))+'</pre></details></div>':'';
  return unsupported+'<div class="fc-visual-editor'+(readonly?' fc-visual-readonly':'')+'">'+library+canvas+panel+'</div>';
}
function selectCanvasNode(id){if(!editor||editor.busy||editor.pending||!editor.values.nodes.some(n=>n.nodeId===id))return;readValues();editor.selectedNodeId=id;editor.expanded=new Set([id]);draw();}
function canvasKey(event,id){if(event.key==='Enter'||event.key===' '){event.preventDefault();selectCanvasNode(id);}}
function addCanvasNode(type,point){
  if(!editableCanvas()||type&&!Object.hasOwn(nodeTypes,type))return;
  readValues();touch();let i=1;while(editor.usedNodeIds.has('node-'+i))i++;const nodeId='node-'+i;editor.usedNodeIds.add(nodeId);
  editor.values.nodes.push({nodeId,name:'',type:type||'',duty:'',methods:[],next:[],targetKind:'',...(v2()?{conditionSource:{scope:'CURRENT_NODE'}}:{})});editor.positions[nodeId]=point||{x:44+((i-1)%3)*250,y:44+Math.floor((i-1)/3)*150};editor.selectedNodeId=nodeId;editor.expanded=new Set([nodeId]);draw();requestAnimationFrame(()=>focusNodeField(nodeId,'name'));
}
function beginLibraryDrag(event,type){if(!editableCanvas()){event.preventDefault();return;}event.dataTransfer.setData('application/x-flow-node',type);event.dataTransfer.effectAllowed='copy';}
function canvasDragOver(event){if(editableCanvas()&&Array.from(event.dataTransfer.types).includes('application/x-flow-node')){event.preventDefault();event.dataTransfer.dropEffect='copy';}}
function dropCanvasNode(event){if(!editableCanvas())return;const type=event.dataTransfer.getData('application/x-flow-node');if(!Object.hasOwn(nodeTypes,type))return;event.preventDefault();const rect=event.currentTarget.getBoundingClientRect();addCanvasNode(type,{x:Math.max(12,Math.round(event.clientX-rect.left-80)),y:Math.max(12,Math.round(event.clientY-rect.top-24))});}
function beginCanvasMove(event,id){
  if(!editableCanvas()||event.button!==0)return;event.preventDefault();event.stopPropagation();readValues();
  const current=editor,start={...editor.positions[id]},node=event.currentTarget.closest('[data-canvas-node]'),canvas=document.getElementById('fcCanvas'),x=event.clientX,y=event.clientY;
  let moved=false;const move=ev=>{if(editor!==current)return;const dx=ev.clientX-x,dy=ev.clientY-y;if(Math.abs(dx)+Math.abs(dy)>3)moved=true;current.positions[id]={x:Math.max(12,Math.min(3000,Math.round(start.x+dx))),y:Math.max(12,Math.min(3000,Math.round(start.y+dy)))};node.style.left=current.positions[id].x+'px';node.style.top=current.positions[id].y+'px';canvas.querySelector('.fc-canvas-links').outerHTML=canvasLinks();};
  const finish=()=>{document.removeEventListener('pointermove',move);document.removeEventListener('pointerup',finish);document.removeEventListener('pointercancel',abort);if(editor!==current)return;if(moved)current.layoutDirty=true;current.selectedNodeId=id;current.expanded=new Set([id]);draw();};
  const abort=()=>{if(editor===current)current.positions[id]=start;finish();};
  document.addEventListener('pointermove',move);document.addEventListener('pointerup',finish,{once:true});document.addEventListener('pointercancel',abort,{once:true});
}
function arrangeCanvas(){if(!editor||editor.busy||editor.pending)return;readValues();editor.positions=initialLayoutIgnoringSaved();if(!editor.readOnly)editor.layoutDirty=true;draw();}
function initialLayoutIgnoringSaved(){const id=editor.id;editor.id='';try{return initialLayout();}finally{editor.id=id;}}

function legacyTemplateEditor(v) {
  const nodes=v.nodes || [],readonly=editor.readOnly,startItems=nodes.map((n,i)=>({value:n.nodeId,label:nodeLabel(n,i)+' · '+n.nodeId}));
  const versionText=editor.id?'原 V'+editor.expectedVersion+' · 本次保存为 V'+(editor.expectedVersion+1):'首次保存为 V1';
  const historical=readonly&&editor.viewVersion!==editor.expectedVersion;
  const history=readonly&&editor.versions.length>1?'<details id="fcHistoryPanel" class="fc-history-panel"'+(editor.historyOpen?' open':'')+' ontoggle="FlowConfiguration.toggleHistory(this.open)"><summary>历史配置 <span>'+e(editor.versions.length-1)+' 个历史版本</span></summary><div class="fc-history-body">'+field('已保存配置','<select id="fcHistoryVersion" onchange="FlowConfiguration.selectHistoryVersion(this.value)">'+options(editor.versions.map(x=>({value:x.version,label:'V'+x.version+(Number(x.version)===editor.expectedVersion?' · 当前配置':' · 历史配置')})),editor.viewVersion)+'</select>','历史配置仅供只读查看，已有业务记录保持原引用。')+'</div></details>':'';
  const notice=historical?'<div id="fcHistoryNotice" class="fc-history-notice"><div><strong>当前查看历史配置 V'+e(editor.viewVersion)+'</strong><span>仅供只读查看；最新配置为 V'+e(editor.expectedVersion)+'。</span></div><button id="fcViewLatest" class="btn" onclick="FlowConfiguration.viewLatest()">返回最新配置</button></div>':readonly?'<div class="fc-detail-status"><span class="fc-version">当前配置 V'+e(editor.viewVersion)+'</span><span>只读详情</span></div>':'';
  const brands=getCatalog(editor.brandId)?.data?.brands || [],brandName=brands.find(b=>(b.brandId || b.id)===editor.brandId)?.name || editor.brandId;
  if(!readonly&&editor.stage==='basics')return '<div class="fc-flow-basics-intro"><strong>先完成基础信息</strong><p>填写模板名称后，进入全屏画布编排节点与路径。</p></div><div class="fc-form-grid">'+field('模板名称 <span class="required">*</span>','<input id="fcName" value="'+e(v.name || '')+'" placeholder="请输入模板名称" oninput="FlowConfiguration.touch()">')+field('所属品牌','<input readonly value="'+e(brandName)+'">')+field('模板系统标识','<input readonly value="'+e(editor.id || '保存时由系统生成')+'">')+field('保存版本','<input readonly value="'+e(versionText)+'">')+'</div>';
  const summary='<div class="fc-canvas-summary"><div><strong data-fc-template-name>'+e(v.name || '未命名模板')+'</strong><p>'+e(brandName)+' · '+e(readonly?'查看 V'+editor.viewVersion:versionText)+'</p></div><div class="fc-canvas-start"><label for="fcStart">起始节点'+(readonly?'':' <span class="required">*</span>')+'</label><select id="fcStart"'+(readonly?' disabled':' onchange="FlowConfiguration.startNodeChanged()"')+'>'+options(startItems,v.startNodeId || '',readonly?'未配置':'请选择起始节点')+'</select></div></div>';
  return notice+summary+visualEditor(v)+history;
}
function syncCanvasFullscreen(enabled) {
  try{return window.parent!==window && window.parent.DModuleHost?.setTemplateEditorFullscreen?.(enabled)===true;}catch(_){return false;}
}
function captureCanvasViewport() {
  if(!editor)return;const viewport=document.getElementById('fcCanvasViewport'),panel=document.querySelector('#'+layerId+' .fc-config-panel'),node=panel?.querySelector('[data-node-id]');
  if(viewport)editor.canvasViewport={top:viewport.scrollTop,left:viewport.scrollLeft};
  if(panel&&node)editor.configScrolls[node.dataset.nodeId]=panel.scrollTop;
}
function restoreCanvasViewport() {
  const current=editor;if(!current||current.stage!=='canvas')return;
  requestAnimationFrame(()=>{if(editor!==current||editor.stage!=='canvas')return;const viewport=document.getElementById('fcCanvasViewport'),panel=document.querySelector('#'+layerId+' .fc-config-panel');if(viewport&&current.canvasViewport){viewport.scrollTop=current.canvasViewport.top;viewport.scrollLeft=current.canvasViewport.left;}if(panel)panel.scrollTop=current.configScrolls[current.selectedNodeId]||0;});
}
function legacyShowCanvas() {
  if(!editor||editor.readOnly||editor.busy||editor.pending)return;readValues();
  if(!String(editor.values.name||'').trim()){status('请输入模板名称后再进入节点编排。','error');document.getElementById('fcName')?.focus();return;}
  if(!isActive())return status('当前工作范围或配置资格已变化，请重新打开表单。','error');
  if(!syncCanvasFullscreen(true))return status('全屏编排暂不可用，请重新打开流转模板。','error');
  editor.stage='canvas';editor.status='';draw();document.querySelector('#'+layerId+' .layer-panel')?.focus({preventScroll:true});
}
function showBasics() {
  if(!editor||editor.readOnly||editor.busy||editor.pending)return;readValues();captureCanvasViewport();editor.stage='basics';editor.status='';draw();document.getElementById('fcName')?.focus({preventScroll:true});
}
