css:
/* Visual flow-template editor. Keep all editor rules inside its existing layer. */
.fc-editor-dialog.fc-visual-dialog {
  width: 1400px !important;
  max-width: calc(100vw - 40px) !important;
}
#flow-configuration-editor .fc-visual-editor {
  display: grid;
  grid-template-columns: 176px minmax(420px, 1fr) 330px;
  gap: 12px;
  align-items: stretch;
  margin-top: 20px;
  min-width: 0;
  border: 1px solid #e2e7ee;
  border-radius: 8px;
  background: #f7f9fc;
  overflow: hidden;
}
#flow-configuration-editor .fc-visual-editor.fc-visual-readonly {
  grid-template-columns: minmax(420px, 1fr) 360px;
}
#flow-configuration-editor .fc-node-library,
#flow-configuration-editor .fc-config-panel {
  min-width: 0;
  background: #fff;
  padding: 16px 12px;
}
#flow-configuration-editor .fc-node-library {
  border-right: 1px solid #e6ebf2;
}
#flow-configuration-editor .fc-node-library h3,
#flow-configuration-editor .fc-node-library h4,
#flow-configuration-editor .fc-config-panel > h3,
#flow-configuration-editor .fc-config-panel > h4 {
  margin: 0 0 12px;
  font-size: 13px;
  font-weight: 600;
  line-height: 20px;
  color: #25364c;
}
#flow-configuration-editor .fc-library-node {
  display: flex;
  width: 100%;
  min-height: 62px;
  flex-direction: column;
  align-items: flex-start;
  justify-content: center;
  gap: 5px;
  margin: 0 0 10px;
  padding: 11px 12px;
  border: 1px solid #e0e6ef;
  border-radius: 6px;
  background: #fff;
  color: #34455d;
  font: inherit;
  font-size: 13px;
  text-align: left;
  cursor: grab;
}
#flow-configuration-editor .fc-library-node:hover {
  border-color: #91caff;
  background: #f4f9ff;
  color: #1677ff;
}
#flow-configuration-editor .fc-library-node:active { cursor: grabbing; }
#flow-configuration-editor .fc-library-node small {
  color: #8a96a7;
  font-size: 11px;
  line-height: 17px;
}
#flow-configuration-editor .fc-library-node:disabled {
  cursor: not-allowed;
  opacity: .5;
}
#flow-configuration-editor .fc-canvas-column {
  min-width: 0;
  padding: 0;
  background: #f7f9fc;
}
#flow-configuration-editor .fc-canvas-toolbar {
  display: flex;
  min-height: 46px;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 8px;
  padding: 9px 12px;
  border-bottom: 1px solid #e6ebf2;
  color: #77869a;
  background: #fff;
  font-size: 12px;
  line-height: 20px;
}
#flow-configuration-editor .fc-canvas-toolbar strong {
  color: #34455d;
  font-size: 13px;
  font-weight: 500;
}
#flow-configuration-editor .fc-canvas-toolbar .btn,
#flow-configuration-editor .fc-canvas-toolbar button {
  min-height: 28px;
  padding: 3px 9px;
  font-size: 12px;
}
#flow-configuration-editor .fc-canvas-viewport {
  height: 480px;
  overflow: auto;
  overscroll-behavior: contain;
  scrollbar-width: thin;
  scrollbar-color: #c8d2df #f2f5f9;
}
#flow-configuration-editor .fc-canvas {
  position: relative;
  min-width: 760px;
  min-height: 650px;
  background-color: #f8fafd;
  background-image: radial-gradient(#dbe3ee 1px, transparent 1px);
  background-size: 18px 18px;
}
#flow-configuration-editor .fc-canvas:focus-visible {
  outline: 2px solid #1677ff;
  outline-offset: -3px;
}
#flow-configuration-editor .fc-canvas-node {
  position: absolute;
  z-index: 2;
  box-sizing: border-box;
  width: 180px;
  min-height: 92px;
  padding: 12px;
  border: 1px solid #d4dce8;
  border-radius: 7px;
  background: #fff;
  color: #33455d;
  font: inherit;
  font-size: 12px;
  text-align: left;
  cursor: grab;
  user-select: none;
